    g.fillStyle = "rgba(0,0,0,0.12)"; g.beginPath(); g.arc(c, c, c, 0, Math.PI * 2); g.arc(c, c, c - 14, 0, Math.PI * 2, true); g.fill(); // rim
    g.fillStyle = g.strokeStyle = "#ffffff"; g.textAlign = "center"; g.textBaseline = "middle"; g.lineCap = "round";
