      g.lineWidth = 16; g.beginPath(); g.ellipse(c, c - 14, 84, 30, 0, 0, Math.PI * 2); g.stroke();
      g.fillStyle = "#26a17b"; g.fillRect(c - 15, c - 40, 30, 52); g.fillStyle = "#ffffff"; g.fillRect(c - 15, c - 40, 30, 22);
