    d.rx = rand(0, 6.28); d.ry = rand(0, 6.28); d.rz = rand(0, 6.28);
    d.phase = rand(0, 6.28);
    d.speed = d.kind === 1 ? rand(0.55, 0.95) : d.kind === 2 ? rand(1.2, 1.7) : rand(1.1, 2);
