  const M4 = new THREE.Matrix4(), Q = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 0, 1), 0.12), V = new THREE.Vector3(), S = new THREE.Vector3(), Q0 = new THREE.Quaternion();

