  for (let i = 0; i < 14; i++) { const x = -44 + (i * 88) / 13, z = 24 + 3 * Math.sin(i * 0.9); LANTERN_PATH.push([x, Math.max(0.2, moundY(x, z)) + 2.0, z]); }
