  const HANG = [[-1, 0.3, 0.9], [-1, 0.52, 0.55], [-1, 0.74, 1.05], [1, 0.4, 0.7], [1, 0.63, 1.0]]; // branch, how far along its limb, cord length
  const FEST = HANG.length, fest = makeLanterns(FEST, near, 21);
